export const AYUDA_COMBATE: { title: string; text: string }[] = [
  {title:'Esquivar y terminar',text:'Esquivar requiere una acción disponible durante tu turno; su efecto continúa hasta el inicio de tu siguiente turno. Gastar la acción no gasta por sí mismo la adicional ni el movimiento. Terminar el turno cede el control: no puedes elegir una nueva defensa para el participante anterior.'},
  { title: 'Turnos', text: 'Cada uno actúa por orden de iniciativa. En tu turno tienes una acción (atacar, conjuro, esquivar, huir…), una acción adicional (pociones y algunos conjuros) y un movimiento (cambiar de fila). Cuando todos han actuado empieza un nuevo asalto (unos 6 segundos dentro del juego, como en el SRD).' },
  { title: 'Filas', text: 'La vanguardia recibe los golpes cuerpo a cuerpo; la retaguardia está a salvo de ellos mientras alguien aguante delante. Si no queda nadie en pie delante (o vas solo), te alcanzan igual. Cuerpo a cuerpo solo se alcanza la fila delantera enemiga; disparos y conjuros llegan a cualquiera. Los tiradores enemigos se ponen detrás y apuntan a tu retaguardia; si un enemigo grande los cubre, atacarlos tiene desventaja.' },
  { title: 'Dados', text: 'El d20 decide si aciertas: verde acierto, rojo fallo, dorado un 20 (crítico, daño doble) y granate un 1. Debajo salen los dados de daño o curación.' },
  { title: 'Caídos', text: 'A 0 PG un personaje cae y tira salvaciones contra la muerte: tres fallos y muere. Curarle le levanta; si el combate acaba antes, se levanta con 1 PG.' },
];

